// Vérifier si un identifiant national existe déjà
app.get('/api/beneficiaires/check-identifiant/:identifiant', authenticateToken, async (req, res) => {
  try {
    const { identifiant } = req.params;
    
    if (!identifiant) {
      return res.status(400).json({
        success: false,
        message: 'Code Matricule requis'
      });
    }
    
    const pool = await dbConfig.getConnection();
    
    const query = `
      SELECT 
        COUNT(*) as count,
        b.ID_BEN,
        b.NOM_BEN,
        b.PRE_BEN
      FROM [core].[BENEFICIAIRE] b
      WHERE b.IDENTIFIANT_NATIONAL = @identifiant
        AND b.RETRAIT_DATE IS NULL
      GROUP BY b.ID_BEN, b.NOM_BEN, b.PRE_BEN
    `;
    
    const result = await pool.request()
      .input('identifiant', sql.VarChar, identifiant)
      .query(query);
    
    const exists = result.recordset.length > 0;
    
    return res.json({
      success: true,
      exists: exists,
      count: exists ? result.recordset[0].count : 0,
      beneficiaire: exists ? {
        id: result.recordset[0].ID_BEN,
        nom: result.recordset[0].NOM_BEN,
        prenom: result.recordset[0].PRE_BEN
      } : null
    });
    
  } catch (error) {
    console.error('Erreur vérification identifiant:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur serveur'
    });
  }
});

// Générer un identifiant national unique
app.get('/api/beneficiaires/generate-identifiant', authenticateToken, async (req, res) => {
  try {
    const pool = await dbConfig.getConnection();
    
    // Générer un identifiant unique (exemple: BEN-YYYYMMDD-XXXXX)
    const date = new Date();
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    
    // Chercher le dernier numéro pour aujourd'hui
    const query = await pool.request().query(`
      SELECT MAX(IDENTIFIANT_NATIONAL) as max_id
      FROM [core].[BENEFICIAIRE]
      WHERE IDENTIFIANT_NATIONAL LIKE 'BEN-${year}${month}${day}-%'
    `);
    
    let nextNumber = 1;
    const maxId = query.recordset[0]?.max_id;
    
    if (maxId) {
      const parts = maxId.split('-');
      if (parts.length === 3) {
        const lastNumber = parseInt(parts[2]) || 0;
        nextNumber = lastNumber + 1;
      }
    }
    
    const newId = `BEN-${year}${month}${day}-${String(nextNumber).padStart(5, '0')}`;
    
    return res.json({
      success: true,
      identifiant: newId
    });
    
  } catch (error) {
    console.error('Erreur génération identifiant:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur serveur'
    });
  }
});

// ==============================================
// ROUTES POUR LES SYNCHRONISATIONS
// ==============================================
/**
 * @route POST /api/sync/ace-data
 * @desc Synchroniser les données ACE (Actualisation des Cotisations des Employés)
 * @access Private
 */
app.post('/api/sync/ace-data', authenticateToken, async (req, res) => {
  try {
    const pool = await dbConfig.getConnection();
    
    // Trouver les bénéficiaires avec STATUT_ACE mais non présents dans BENEFICIAIRE_ACE
    const query = `
      SELECT b.ID_BEN, b.STATUT_ACE, b.ID_ASSURE_PRINCIPAL
      FROM [core].[BENEFICIAIRE] b
      LEFT JOIN [core].[BENEFICIAIRE_ACE] a ON b.ID_BEN = a.ID_BEN
      WHERE b.STATUT_ACE IS NOT NULL
        AND a.ID_ACE IS NULL
        AND b.RETRAIT_DATE IS NULL
    `;
    
    const result = await pool.request().query(query);
    
    const syncResults = [];
    const statistics = {
      synced: 0,
      errors: 0,
      total: result.recordset.length
    };
    
    for (const row of result.recordset) {
      try {
        const syncQuery = `
          INSERT INTO [core].[BENEFICIAIRE_ACE] (
            ID_BEN,
            STATUT_ACE,
            ID_ASSURE_PRINCIPAL,
            DATE_CREUTIL
          )
          VALUES (
            @ID_BEN,
            @STATUT_ACE,
            @ID_ASSURE_PRINCIPAL,
            GETDATE()
          )
        `;
        
        await pool.request()
          .input('ID_BEN', sql.Int, row.ID_BEN)
          .input('STATUT_ACE', sql.VarChar, row.STATUT_ACE)
          .input('ID_ASSURE_PRINCIPAL', sql.Int, row.ID_ASSURE_PRINCIPAL)
          .query(syncQuery);
        
        syncResults.push({
          id_ben: row.ID_BEN,
          status: 'synced'
        });
        statistics.synced++;
      } catch (error) {
        syncResults.push({
          id_ben: row.ID_BEN,
          status: 'error',
          error: error.message
        });
        statistics.errors++;
      }
    }
    
    return res.json({
      success: true,
      data: {
        results: syncResults,
        statistics: statistics,
        summary: {
          message: `Synchronisation terminée. ${statistics.synced} enregistrements synchronisés, ${statistics.errors} erreurs.`,
          successRate: statistics.total > 0 ? (statistics.synced / statistics.total * 100).toFixed(2) + '%' : 'N/A'
        }
      }
    });
    
  } catch (error) {
    console.error('Erreur synchronisation ACE:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur serveur lors de la synchronisation ACE',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

/**
 * @route POST /api/sync/global
 * @desc Synchronisation globale des prestataires avec les systèmes externes
 * @access Private
 */
app.post('/api/sync/global', authenticateToken, async (req, res) => {
  let pool;
  try {
    pool = await dbConfig.getConnection();
    
    // Récupération et validation des paramètres
    const {
      scope = 'all',
      direction = 'bidirectional',
      entityTypes = ['prestataire', 'centre'],
      options = {
        validateBeforeSync: false,
        createBackup: false,
        notifyUsers: false,
        forceUpdate: false,
        includeAssociations: true,
        maxRecords: 1000,
        fillMissingAssociations: true,
        syncTaxesFromCentre: true,
        defaultAssociationDates: true
      },
      prestataireIds = [],
      centreIds = []
    } = req.body;

    // Validation des paramètres
    if (!Array.isArray(entityTypes) || entityTypes.length === 0) {
      return res.status(400).json({
        success: false,
        message: 'Le paramètre entityTypes doit être un tableau non vide'
      });
    }

    // Initialisation des résultats
    const syncResults = {
      prestataires: [],
      centres: [],
      associations: [],
      fillOperations: [],
      validation: {
        prestatairesWithInvalidCentre: [],
        centresNotFound: []
      }
    };

    const statistics = {
      totalProcessed: 0,
      synced: 0,
      errors: 0,
      skipped: 0,
      associationsCreated: 0,
      associationsUpdated: 0,
      validationErrors: 0
    };

    // ==================== PHASE 1: VALIDATION DES DONNÉES ====================
    if (options.validateBeforeSync) {
      console.log('🔍 Début de la validation des données...');
      
      // Validation 1: Vérifier les prestataires avec centre invalide
      try {
        const invalidPrestatairesQuery = `
          SELECT 
            p.COD_PRE,
            p.COD_CEN,
            p.NOM_PRESTATAIRE,
            p.PRENOM_PRESTATAIRE,
            CASE 
              WHEN c.COD_CEN IS NULL THEN 'CENTRE_INEXISTANT'
              WHEN p.COD_CEN IS NULL OR p.COD_CEN = '' THEN 'COD_CEN_VIDE'
              ELSE 'OK'
            END as statut
          FROM [hcs_backoffice].[core].[PRESTATAIRE] p
          LEFT JOIN [hcs_backoffice].[core].[CENTRE] c ON p.COD_CEN = c.COD_CEN
          WHERE p.COD_CEN IS NOT NULL 
            AND p.COD_CEN != ''
            AND (c.COD_CEN IS NULL OR p.COD_CEN = '' OR TRIM(p.COD_CEN) = '')
        `;

        const invalidPrestatairesResult = await pool.request().query(invalidPrestatairesQuery);
        
        if (invalidPrestatairesResult.recordset.length > 0) {
          console.warn(`⚠️ ${invalidPrestatairesResult.recordset.length} prestataires avec centre invalide détectés`);
          
          syncResults.validation.prestatairesWithInvalidCentre = invalidPrestatairesResult.recordset.map(row => ({
            cod_pre: row.COD_PRE,
            cod_cen: row.COD_CEN,
            nom: `${row.PRENOM_PRESTATAIRE} ${row.NOM_PRESTATAIRE}`,
            issue: row.statut
          }));
          
          statistics.validationErrors += invalidPrestatairesResult.recordset.length;
          
          // Si on ne force pas la synchronisation, on retourne une erreur
          if (!options.forceUpdate && invalidPrestatairesResult.recordset.length > 0) {
            return res.status(400).json({
              success: false,
              message: 'Des données incohérentes ont été détectées',
              validationErrors: syncResults.validation,
              action: 'Corrigez les données avant de synchroniser ou activez forceUpdate pour ignorer ces erreurs'
            });
          }
        }
      } catch (validationError) {
        console.error('❌ Erreur lors de la validation:', validationError);
      }
    }

    // ==================== PHASE 2: SYNCHRONISATION DES PRESTATAIRES ====================
    if (entityTypes.includes('prestataire')) {
      try {
        let prestataireQuery = `
          SELECT TOP (${options.maxRecords}) 
            [COD_PRE],
            [COD_PAY],
            [TYPE_PRESTATAIRE],
            [NOM_PRESTATAIRE],
            [PRENOM_PRESTATAIRE],
            [SPECIALITE],
            [TITRE],
            [NUM_LICENCE],
            [NUM_ORDRE],
            [DATE_OBTENTION_LICENCE],
            [DATE_EXPIRATION_LICENCE],
            [UNIVERSITE_FORMATION],
            [ANNEE_DIPLOME],
            [NUM_ADR],
            [TELEPHONE],
            [EMAIL],
            [CENTRE_PRATIQUE],
            [COD_CEN],
            [HONORAIRES],
            [LANGUE_PARLEE],
            [EXPERIENCE_ANNEE],
            [DISPONIBILITE],
            [ACTIF],
            [COD_CREUTIL],
            [COD_MODUTIL],
            [DAT_CREUTIL],
            [DAT_MODUTIL]
          FROM [hcs_backoffice].[core].[PRESTATAIRE]
          WHERE 1=1
        `;

        const request = pool.request();

        // Application des filtres selon le scope
        if (scope === 'active') {
          prestataireQuery += ` AND ACTIF = 1`;
        } else if (scope === 'recent') {
          const recentDate = new Date();
          recentDate.setDate(recentDate.getDate() - 7);
          prestataireQuery += ` AND (DAT_MODUTIL >= @recentDate OR DAT_CREUTIL >= @recentDate)`;
          request.input('recentDate', sql.DateTime, recentDate);
        } else if (scope === 'selected' && prestataireIds.length > 0) {
          const placeholders = prestataireIds.map((_, i) => `@cod_pre_${i}`).join(',');
          prestataireQuery += ` AND COD_PRE IN (${placeholders})`;
          prestataireIds.forEach((id, i) => {
            request.input(`cod_pre_${i}`, sql.VarChar(50), String(id));
          });
        }

        const prestataireResult = await request.query(prestataireQuery);
        statistics.totalProcessed += prestataireResult.recordset.length;

        // Traitement de chaque prestataire
        for (const prestataire of prestataireResult.recordset) {
          try {
            // Validation du COD_PRE
            if (!prestataire.COD_PRE) {
              console.error(`❌ COD_PRE manquant pour le prestataire:`, prestataire);
              syncResults.prestataires.push({
                cod_pre: 'unknown',
                status: 'error',
                error: 'COD_PRE manquant'
              });
              statistics.errors++;
              continue;
            }

            const codPreString = String(prestataire.COD_PRE).trim();

            // Synchronisation selon la direction
            if (direction === 'upload' || direction === 'bidirectional') {
              const updateQuery = `
                UPDATE [hcs_backoffice].[core].[PRESTATAIRE]
                SET 
                  COD_MODUTIL = @COD_MODUTIL,
                  DAT_MODUTIL = GETDATE()
                WHERE COD_PRE = @COD_PRE
              `;
              
              await pool.request()
                .input('COD_PRE', sql.VarChar(50), codPreString)
                .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system')
                .query(updateQuery);
            }

            syncResults.prestataires.push({
              cod_pre: codPreString,
              status: 'synced',
              direction: direction,
              details: {
                nom: prestataire.NOM_PRESTATAIRE,
                prenom: prestataire.PRENOM_PRESTATAIRE,
                centre_principal: prestataire.COD_CEN
              },
              timestamp: new Date().toISOString()
            });
            statistics.synced++;

          } catch (error) {
            console.error(`❌ Erreur synchronisation prestataire ${prestataire.COD_PRE}:`, error);
            syncResults.prestataires.push({
              cod_pre: prestataire.COD_PRE || 'unknown',
              status: 'error',
              error: error.message
            });
            statistics.errors++;
          }
        }
      } catch (error) {
        console.error('❌ Erreur récupération des prestataires:', error);
        syncResults.prestataires.push({
          status: 'error',
          error: `Erreur lors de la récupération des prestataires: ${error.message}`
        });
      }
    }

    // ==================== PHASE 3: SYNCHRONISATION DES CENTRES ====================
    if (entityTypes.includes('centre')) {
      try {
        let centreQuery = `
          SELECT TOP (${options.maxRecords}) 
            [COD_CEN],
            [COD_PAY],
            [COD_PAI],
            [LIB_CEN],
            [OBS_CEN],
            [ORD_CEN],
            [AUT_CEN],
            [NUM_ADR],
            [NUM_RIB],
            [ENR_CEN],
            [TR1_CEN],
            [TR2_CEN],
            [TR3_CEN],
            [TPS_CEN],
            [TVA_CEN],
            [DEB_AGR],
            [FIN_AGR],
            [DEB_CEN],
            [FIN_CEN],
            [BIO_CEN],
            [AGR_CEN],
            [COD_CREUTIL],
            [COD_MODUTIL],
            [DAT_CREUTIL],
            [DAT_MODUTIL],
            [TYP_CEN],
            [COD_TAR],
            [NCP_CEN],
            [PRM_CEN],
            [COD_NAT]
          FROM [hcs_backoffice].[core].[CENTRE]
          WHERE 1=1
        `;

        const request = pool.request();

        // Application des filtres
        if (scope === 'active') {
          centreQuery += ` AND ENR_CEN = 1`;
        } else if (scope === 'recent') {
          const recentDate = new Date();
          recentDate.setDate(recentDate.getDate() - 7);
          centreQuery += ` AND (DAT_MODUTIL >= @recentDate OR DAT_CREUTIL >= @recentDate)`;
          request.input('recentDate', sql.DateTime, recentDate);
        } else if (scope === 'selected' && centreIds.length > 0) {
          const placeholders = centreIds.map((_, i) => `@cod_cen_${i}`).join(',');
          centreQuery += ` AND COD_CEN IN (${placeholders})`;
          centreIds.forEach((id, i) => {
            request.input(`cod_cen_${i}`, sql.VarChar(50), String(id));
          });
        }

        const centreResult = await request.query(centreQuery);
        statistics.totalProcessed += centreResult.recordset.length;

        // Traitement de chaque centre
        for (const centre of centreResult.recordset) {
          try {
            // Vérifier que COD_CEN existe
            if (!centre.COD_CEN) {
              console.error(`❌ COD_CEN manquant pour le centre:`, centre);
              syncResults.centres.push({
                cod_cen: 'unknown',
                status: 'error',
                error: 'COD_CEN manquant'
              });
              statistics.errors++;
              continue;
            }

            const codCenString = String(centre.COD_CEN).trim();

            // Synchronisation selon la direction
            if (direction === 'upload' || direction === 'bidirectional') {
              const updateQuery = `
                UPDATE [hcs_backoffice].[core].[CENTRE]
                SET 
                  COD_MODUTIL = @COD_MODUTIL,
                  DAT_MODUTIL = GETDATE()
                WHERE COD_CEN = @COD_CEN
              `;
              
              await pool.request()
                .input('COD_CEN', sql.VarChar(50), codCenString)
                .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system')
                .query(updateQuery);
            }

            syncResults.centres.push({
              cod_cen: codCenString,
              status: 'synced',
              direction: direction,
              details: {
                libelle: centre.LIB_CEN,
                type: centre.TYP_CEN,
                pays: centre.COD_PAY
              },
              timestamp: new Date().toISOString()
            });
            statistics.synced++;

          } catch (error) {
            console.error(`❌ Erreur synchronisation centre ${centre.COD_CEN}:`, error);
            syncResults.centres.push({
              cod_cen: centre.COD_CEN || 'unknown',
              status: 'error',
              error: error.message
            });
            statistics.errors++;
          }
        }
      } catch (error) {
        console.error('❌ Erreur récupération des centres:', error);
        syncResults.centres.push({
          status: 'error',
          error: `Erreur lors de la récupération des centres: ${error.message}`
        });
      }
    }

    // ==================== PHASE 4: SYNCHRONISATION DES ASSOCIATIONS EXISTANTES ====================
    if (options.includeAssociations && entityTypes.includes('prestataire') && entityTypes.includes('centre')) {
      try {
        let associationQuery = `
          SELECT TOP (${options.maxRecords}) 
            [NUM_PRECEN],
            [COD_PAY],
            [COD_PRE],
            [COD_CEN],
            [DEB_AGRP],
            [FIN_AGRP],
            [OBS_AGRP],
            [TR1_AGRP],
            [TR2_AGRP],
            [TR3_AGRP],
            [TPS_AGRP],
            [TVA_AGRP],
            [COD_CREUTIL],
            [COD_MODUTIL],
            [DAT_CREUTIL],
            [DAT_MODUTIL]
          FROM [hcs_backoffice].[core].[CENTRE_PRESTATAIRE]
          WHERE 1=1
        `;

        const request = pool.request();
        const whereConditions = [];
        
        if (prestataireIds.length > 0) {
          const placeholders = prestataireIds.map((_, i) => `@cod_pre_${i}`).join(',');
          whereConditions.push(`COD_PRE IN (${placeholders})`);
          prestataireIds.forEach((id, i) => {
            request.input(`cod_pre_${i}`, sql.VarChar(50), String(id));
          });
        }
        
        if (centreIds.length > 0) {
          const placeholders = centreIds.map((_, i) => `@cod_cen_${i}`).join(',');
          whereConditions.push(`COD_CEN IN (${placeholders})`);
          centreIds.forEach((id, i) => {
            request.input(`cod_cen_${i}`, sql.VarChar(50), String(id));
          });
        }
        
        if (scope === 'recent') {
          const recentDate = new Date();
          recentDate.setDate(recentDate.getDate() - 7);
          whereConditions.push(`(DAT_MODUTIL >= @recentDate OR DAT_CREUTIL >= @recentDate)`);
          request.input('recentDate', sql.DateTime, recentDate);
        }
        
        if (whereConditions.length > 0) {
          associationQuery += ` AND (${whereConditions.join(' OR ')})`;
        }

        const associationResult = await request.query(associationQuery);
        statistics.totalProcessed += associationResult.recordset.length;

        // Traitement de chaque association
        for (const association of associationResult.recordset) {
          try {
            // Vérifier que les codes existent
            if (!association.COD_PRE || !association.COD_CEN) {
              console.error(`❌ Données manquantes pour l'association ${association.NUM_PRECEN}:`, association);
              syncResults.associations.push({
                num_precen: association.NUM_PRECEN,
                status: 'error',
                error: 'COD_PRE ou COD_CEN manquant'
              });
              statistics.errors++;
              continue;
            }

            // Mise à jour des métadonnées
            const updateQuery = `
              UPDATE [hcs_backoffice].[core].[CENTRE_PRESTATAIRE]
              SET 
                COD_MODUTIL = @COD_MODUTIL,
                DAT_MODUTIL = GETDATE()
              WHERE NUM_PRECEN = @NUM_PRECEN
            `;
            
            await pool.request()
              .input('NUM_PRECEN', sql.Int, association.NUM_PRECEN)
              .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system')
              .query(updateQuery);

            syncResults.associations.push({
              num_precen: association.NUM_PRECEN,
              status: 'synced',
              details: {
                cod_pre: String(association.COD_PRE),
                cod_cen: String(association.COD_CEN),
                periode: {
                  debut: association.DEB_AGRP,
                  fin: association.FIN_AGRP
                }
              },
              timestamp: new Date().toISOString()
            });
            statistics.synced++;

          } catch (error) {
            console.error(`❌ Erreur synchronisation association ${association.NUM_PRECEN}:`, error);
            syncResults.associations.push({
              num_precen: association.NUM_PRECEN,
              status: 'error',
              error: error.message
            });
            statistics.errors++;
          }
        }
      } catch (error) {
        console.error('❌ Erreur récupération des associations:', error);
        syncResults.associations.push({
          status: 'error',
          error: `Erreur lors de la récupération des associations: ${error.message}`
        });
      }
    }

    // ==================== PHASE 5: REMPLISSAGE DES ASSOCIATIONS MANQUANTES ====================
    if (options.fillMissingAssociations && entityTypes.includes('prestataire') && entityTypes.includes('centre')) {
      try {
        console.log('🔄 Début du remplissage des associations manquantes...');
        
        // Récupérer les prestataires avec centre principal VALIDE (qui existe dans la table CENTRE)
        const validPrestatairesQuery = `
          SELECT DISTINCT
            p.COD_PRE,
            p.COD_PAY,
            p.COD_CEN,
            p.COD_CREUTIL,
            p.COD_MODUTIL,
            c.TR1_CEN,
            c.TR2_CEN,
            c.TR3_CEN,
            c.TPS_CEN,
            c.TVA_CEN,
            p.NOM_PRESTATAIRE,
            p.PRENOM_PRESTATAIRE,
            c.LIB_CEN
          FROM [hcs_backoffice].[core].[PRESTATAIRE] p
          INNER JOIN [hcs_backoffice].[core].[CENTRE] c ON p.COD_CEN = c.COD_CEN
          WHERE p.COD_CEN IS NOT NULL 
            AND p.COD_CEN != ''
            AND TRIM(p.COD_CEN) != ''
            AND c.COD_CEN IS NOT NULL
        `;

        // Appliquer les filtres selon le scope
        let finalQuery = validPrestatairesQuery;
        const request = pool.request();
        
        if (scope === 'active') {
          finalQuery += ` AND p.ACTIF = 1`;
        } else if (scope === 'selected' && prestataireIds.length > 0) {
          const placeholders = prestataireIds.map((_, i) => `@cod_pre_${i}`).join(',');
          finalQuery += ` AND p.COD_PRE IN (${placeholders})`;
          prestataireIds.forEach((id, i) => {
            request.input(`cod_pre_${i}`, sql.VarChar(50), String(id));
          });
        }

        const validPrestatairesResult = await request.query(finalQuery);
        
        console.log(`📊 ${validPrestatairesResult.recordset.length} prestataires avec centre principal valide trouvés`);

        // Pour chaque prestataire, créer l'association si elle n'existe pas
        for (const prestataire of validPrestatairesResult.recordset) {
          try {
            const codPreString = String(prestataire.COD_PRE).trim();
            const codCenString = String(prestataire.COD_CEN).trim();

            // Validation supplémentaire
            if (!codPreString || codPreString === '') {
              console.warn(`⚠️ COD_PRE vide ou invalide pour le prestataire:`, prestataire);
              continue;
            }

            if (!codCenString || codCenString === '') {
              console.warn(`⚠️ COD_CEN vide ou invalide pour le prestataire ${codPreString}`);
              continue;
            }

            // Vérifier si l'association existe déjà
            const checkAssociationQuery = `
              SELECT COUNT(*) as count, MAX(NUM_PRECEN) as num_precen
              FROM [hcs_backoffice].[core].[CENTRE_PRESTATAIRE]
              WHERE COD_PRE = @COD_PRE AND COD_CEN = @COD_CEN
            `;

            const checkResult = await pool.request()
              .input('COD_PRE', sql.VarChar(50), codPreString)
              .input('COD_CEN', sql.VarChar(50), codCenString)
              .query(checkAssociationQuery);

            if (checkResult.recordset[0].count > 0) {
              // L'association existe déjà
              console.log(`✓ Association déjà existante: ${codPreString} -> ${codCenString} (ID: ${checkResult.recordset[0].num_precen})`);
              continue;
            }

            // Créer l'association manquante
            const insertQuery = `
              INSERT INTO [hcs_backoffice].[core].[CENTRE_PRESTATAIRE] (
                [COD_PAY],
                [COD_PRE],
                [COD_CEN],
                [DEB_AGRP],
                [FIN_AGRP],
                [OBS_AGRP],
                [TR1_AGRP],
                [TR2_AGRP],
                [TR3_AGRP],
                [TPS_AGRP],
                [TVA_AGRP],
                [COD_CREUTIL],
                [COD_MODUTIL],
                [DAT_CREUTIL],
                [DAT_MODUTIL]
              ) VALUES (
                @COD_PAY,
                @COD_PRE,
                @COD_CEN,
                @DEB_AGRP,
                @FIN_AGRP,
                @OBS_AGRP,
                @TR1_AGRP,
                @TR2_AGRP,
                @TR3_AGRP,
                @TPS_AGRP,
                @TVA_AGRP,
                @COD_CREUTIL,
                @COD_MODUTIL,
                GETDATE(),
                GETDATE()
              );
              
              SELECT SCOPE_IDENTITY() as new_id;
            `;

            // Préparer les valeurs
            const now = new Date();
            const defaultStartDate = options.defaultAssociationDates ? now : null;
            const defaultEndDate = options.defaultAssociationDates ? 
              new Date(now.getFullYear() + 1, now.getMonth(), now.getDate()) : null;

            const insertRequest = pool.request()
              .input('COD_PAY', sql.VarChar(50), prestataire.COD_PAY || '')
              .input('COD_PRE', sql.VarChar(50), codPreString)
              .input('COD_CEN', sql.VarChar(50), codCenString)
              .input('DEB_AGRP', sql.DateTime, defaultStartDate)
              .input('FIN_AGRP', sql.DateTime, defaultEndDate)
              .input('OBS_AGRP', sql.VarChar(sql.MAX), `Association créée automatiquement pour ${prestataire.PRENOM_PRESTATAIRE} ${prestataire.NOM_PRESTATAIRE} avec ${prestataire.LIB_CEN} le ${now.toISOString()}`)
              .input('COD_CREUTIL', sql.VarChar(50), req.user?.username || 'system')
              .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system');

            // Copier les taxes du centre si l'option est activée
            if (options.syncTaxesFromCentre && prestataire.TR1_CEN !== undefined) {
              insertRequest
                .input('TR1_AGRP', sql.Decimal(18, 2), prestataire.TR1_CEN || 0)
                .input('TR2_AGRP', sql.Decimal(18, 2), prestataire.TR2_CEN || 0)
                .input('TR3_AGRP', sql.Decimal(18, 2), prestataire.TR3_CEN || 0)
                .input('TPS_AGRP', sql.Decimal(18, 2), prestataire.TPS_CEN || 0)
                .input('TVA_AGRP', sql.Decimal(18, 2), prestataire.TVA_CEN || 0);
            } else {
              insertRequest
                .input('TR1_AGRP', sql.Decimal(18, 2), 0)
                .input('TR2_AGRP', sql.Decimal(18, 2), 0)
                .input('TR3_AGRP', sql.Decimal(18, 2), 0)
                .input('TPS_AGRP', sql.Decimal(18, 2), 0)
                .input('TVA_AGRP', sql.Decimal(18, 2), 0);
            }

            const insertResult = await insertRequest.query(insertQuery);
            const newAssociationId = insertResult.recordset[0]?.new_id;

            syncResults.fillOperations.push({
              status: 'created',
              type: 'association',
              details: {
                num_precen: newAssociationId,
                cod_pre: codPreString,
                cod_cen: codCenString,
                prestataire: `${prestataire.PRENOM_PRESTATAIRE} ${prestataire.NOM_PRESTATAIRE}`,
                centre: prestataire.LIB_CEN,
                source: 'automatic_fill',
                taxes_copied: options.syncTaxesFromCentre
              },
              timestamp: new Date().toISOString()
            });

            statistics.associationsCreated++;
            console.log(`✅ Association créée: ${codPreString} -> ${codCenString} (ID: ${newAssociationId})`);

          } catch (error) {
            console.error(`❌ Erreur création association pour ${prestataire.COD_PRE}:`, error);
            
            // Log détaillé en cas d'erreur FK
            if (error.number === 547) {
              console.error(`🔍 Erreur FK - Prestataire: ${prestataire.COD_PRE}, Centre: ${prestataire.COD_CEN}`);
            }
            
            syncResults.fillOperations.push({
              status: 'error',
              type: 'association',
              details: {
                cod_pre: prestataire.COD_PRE,
                cod_cen: prestataire.COD_CEN,
                error: error.message,
                errorCode: error.number
              }
            });
            statistics.errors++;
          }
        }

        // Mise à jour des taxes des associations existantes
        if (options.syncTaxesFromCentre) {
          try {
            console.log('🔄 Mise à jour des taxes des associations existantes...');
            
            const updateTaxesQuery = `
              UPDATE cp
              SET 
                cp.TR1_AGRP = ISNULL(c.TR1_CEN, cp.TR1_AGRP),
                cp.TR2_AGRP = ISNULL(c.TR2_CEN, cp.TR2_AGRP),
                cp.TR3_AGRP = ISNULL(c.TR3_CEN, cp.TR3_AGRP),
                cp.TPS_AGRP = ISNULL(c.TPS_CEN, cp.TPS_AGRP),
                cp.TVA_AGRP = ISNULL(c.TVA_CEN, cp.TVA_AGRP),
                cp.COD_MODUTIL = @COD_MODUTIL,
                cp.DAT_MODUTIL = GETDATE()
              FROM [hcs_backoffice].[core].[CENTRE_PRESTATAIRE] cp
              INNER JOIN [hcs_backoffice].[core].[CENTRE] c ON cp.COD_CEN = c.COD_CEN
              WHERE cp.COD_CEN IS NOT NULL
            `;

            const updateResult = await pool.request()
              .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system')
              .query(updateTaxesQuery);

            statistics.associationsUpdated = updateResult.rowsAffected[0] || 0;
            
            console.log(`✅ ${statistics.associationsUpdated} associations mises à jour avec les taxes du centre`);
            
            syncResults.fillOperations.push({
              status: 'updated',
              type: 'taxes_update',
              details: {
                count: statistics.associationsUpdated,
                message: `Taxes mises à jour pour ${statistics.associationsUpdated} associations`
              }
            });

          } catch (error) {
            console.error('❌ Erreur mise à jour des taxes:', error);
            syncResults.fillOperations.push({
              status: 'error',
              type: 'taxes_update',
              error: error.message
            });
          }
        }

        console.log(`🎉 Remplissage terminé: ${statistics.associationsCreated} associations créées, ${statistics.associationsUpdated} mises à jour`);

      } catch (error) {
        console.error('❌ Erreur lors du remplissage des associations:', error);
        syncResults.fillOperations.push({
          status: 'error',
          type: 'fill_process',
          error: error.message
        });
      }
    }

    // ==================== PHASE 6: SAUVEGARDE ====================
    let backupInfo = null;
    if (options.createBackup && (statistics.synced > 0 || statistics.associationsCreated > 0)) {
      try {
        const backupTimestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const backupTableName = `BACKUP_SYNC_${backupTimestamp}`;
        
        const createBackupQuery = `
          SELECT * INTO [hcs_backoffice].[backup].[${backupTableName}]
          FROM (
            SELECT 
              'prestataire' as entity_type,
              COD_PRE as entity_id,
              DAT_MODUTIL as last_sync,
              GETDATE() as backup_date
            FROM [hcs_backoffice].[core].[PRESTATAIRE]
            WHERE DAT_MODUTIL > DATEADD(minute, -5, GETDATE())
            
            UNION ALL
            
            SELECT 
              'centre' as entity_type,
              COD_CEN as entity_id,
              DAT_MODUTIL as last_sync,
              GETDATE() as backup_date
            FROM [hcs_backoffice].[core].[CENTRE]
            WHERE DAT_MODUTIL > DATEADD(minute, -5, GETDATE())
            
            UNION ALL
            
            SELECT 
              'association' as entity_type,
              CAST(NUM_PRECEN as varchar) as entity_id,
              DAT_MODUTIL as last_sync,
              GETDATE() as backup_date
            FROM [hcs_backoffice].[core].[CENTRE_PRESTATAIRE]
            WHERE DAT_MODUTIL > DATEADD(minute, -5, GETDATE())
          ) as sync_data
        `;
        
        await pool.request().query(createBackupQuery);
        
        backupInfo = {
          success: true,
          message: 'Backup créé avec succès',
          table_name: backupTableName,
          records_backed_up: statistics.synced + statistics.associationsCreated
        };
      } catch (backupError) {
        console.error('⚠️ Erreur création backup:', backupError.message);
        backupInfo = {
          success: false,
          error: backupError.message
        };
      }
    }

    // ==================== PHASE 7: NOTIFICATION ====================
    if (options.notifyUsers && req.user?.email) {
      try {
        await sendSyncNotification(req.user.email, {
          statistics,
          syncResults,
          scope,
          direction,
          entityTypes
        });
      } catch (notificationError) {
        console.error('⚠️ Erreur envoi notification:', notificationError.message);
      }
    }

    // ==================== PHASE 8: PRÉPARATION DE LA RÉPONSE ====================
    const successRate = statistics.totalProcessed > 0 
      ? ((statistics.synced / statistics.totalProcessed) * 100).toFixed(2)
      : 0;

    const response = {
      success: statistics.errors === 0 || options.forceUpdate,
      data: {
        metadata: {
          timestamp: new Date().toISOString(),
          user: req.user?.username || 'system',
          scope,
          direction,
          entityTypes,
          options
        },
        statistics: {
          ...statistics,
          successRate: `${successRate}%`,
          details: {
            prestataires: syncResults.prestataires.length,
            centres: syncResults.centres.length,
            associations: syncResults.associations.length,
            fillOperations: syncResults.fillOperations.length,
            validationErrors: statistics.validationErrors
          }
        },
        results: {
          prestataires: syncResults.prestataires.slice(0, 50),
          centres: syncResults.centres.slice(0, 50),
          associations: syncResults.associations.slice(0, 50),
          fillOperations: syncResults.fillOperations
        },
        summary: {
          message: `Synchronisation terminée. ${statistics.synced} entités synchronisées, ${statistics.errors} erreurs, ${statistics.associationsCreated} associations créées, ${statistics.associationsUpdated} associations mises à jour.`,
          status: statistics.errors === 0 ? 'completed_successfully' : 
                  (options.forceUpdate ? 'completed_with_errors' : 'partially_completed')
        },
        backup: backupInfo,
        fillSummary: {
          associationsCreated: statistics.associationsCreated,
          associationsUpdated: statistics.associationsUpdated,
          totalAssociations: statistics.associationsCreated + statistics.associationsUpdated
        }
      }
    };

    // Ajouter les erreurs de validation si elles existent
    if (statistics.validationErrors > 0) {
      response.data.validation = syncResults.validation;
    }

    return res.json(response);

  } catch (error) {
    console.error('❌ Erreur synchronisation globale:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur serveur lors de la synchronisation globale',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined,
      timestamp: new Date().toISOString()
    });
  } finally {
    if (pool) {
      try {
        await pool.close();
      } catch (closeError) {
        console.error('❌ Erreur fermeture connexion:', closeError);
      }
    }
  }
});

app.post('/api/sync/global', authenticateToken, async (req, res) => {
  let pool;
  try {
    pool = await dbConfig.getConnection();
    
    // Récupération et validation des paramètres
    const {
      scope = 'all',
      direction = 'bidirectional',
      entityTypes = ['prestataire', 'centre'],
      options = {
        validateBeforeSync: false,
        createBackup: false,
        notifyUsers: false,
        forceUpdate: false,
        includeAssociations: true,
        maxRecords: 1000,
        fillMissingAssociations: true,
        syncTaxesFromCentre: true,
        defaultAssociationDates: true
      },
      prestataireIds = [],
      centreIds = []
    } = req.body;

    // Validation des paramètres
    if (!Array.isArray(entityTypes) || entityTypes.length === 0) {
      return res.status(400).json({
        success: false,
        message: 'Le paramètre entityTypes doit être un tableau non vide'
      });
    }

    // Initialisation des résultats
    const syncResults = {
      prestataires: [],
      centres: [],
      associations: [],
      fillOperations: [],
      validation: {
        prestatairesWithInvalidCentre: [],
        centresNotFound: []
      }
    };

    const statistics = {
      totalProcessed: 0,
      synced: 0,
      errors: 0,
      skipped: 0,
      associationsCreated: 0,
      associationsUpdated: 0,
      validationErrors: 0
    };

    // ==================== PHASE 1: VALIDATION DES DONNÉES ====================
    if (options.validateBeforeSync) {
      console.log('🔍 Début de la validation des données...');
      
      // Validation 1: Vérifier les prestataires avec centre invalide
      try {
        const invalidPrestatairesQuery = `
          SELECT 
            p.COD_PRE,
            p.COD_CEN,
            p.NOM_PRESTATAIRE,
            p.PRENOM_PRESTATAIRE,
            CASE 
              WHEN c.COD_CEN IS NULL THEN 'CENTRE_INEXISTANT'
              WHEN p.COD_CEN IS NULL OR p.COD_CEN = '' THEN 'COD_CEN_VIDE'
              ELSE 'OK'
            END as statut
          FROM [hcs_backoffice].[core].[PRESTATAIRE] p
          LEFT JOIN [hcs_backoffice].[core].[CENTRE] c ON p.COD_CEN = c.COD_CEN
          WHERE p.COD_CEN IS NOT NULL 
            AND p.COD_CEN != ''
            AND (c.COD_CEN IS NULL OR p.COD_CEN = '' OR TRIM(p.COD_CEN) = '')
        `;

        const invalidPrestatairesResult = await pool.request().query(invalidPrestatairesQuery);
        
        if (invalidPrestatairesResult.recordset.length > 0) {
          console.warn(`⚠️ ${invalidPrestatairesResult.recordset.length} prestataires avec centre invalide détectés`);
          
          syncResults.validation.prestatairesWithInvalidCentre = invalidPrestatairesResult.recordset.map(row => ({
            cod_pre: row.COD_PRE,
            cod_cen: row.COD_CEN,
            nom: `${row.PRENOM_PRESTATAIRE} ${row.NOM_PRESTATAIRE}`,
            issue: row.statut
          }));
          
          statistics.validationErrors += invalidPrestatairesResult.recordset.length;
          
          // Si on ne force pas la synchronisation, on retourne une erreur
          if (!options.forceUpdate && invalidPrestatairesResult.recordset.length > 0) {
            return res.status(400).json({
              success: false,
              message: 'Des données incohérentes ont été détectées',
              validationErrors: syncResults.validation,
              action: 'Corrigez les données avant de synchroniser ou activez forceUpdate pour ignorer ces erreurs'
            });
          }
        }
      } catch (validationError) {
        console.error('❌ Erreur lors de la validation:', validationError);
      }
    }

    // ==================== PHASE 2: SYNCHRONISATION DES PRESTATAIRES ====================
    if (entityTypes.includes('prestataire')) {
      try {
        let prestataireQuery = `
          SELECT TOP (${options.maxRecords}) 
            [COD_PRE],
            [COD_PAY],
            [TYPE_PRESTATAIRE],
            [NOM_PRESTATAIRE],
            [PRENOM_PRESTATAIRE],
            [SPECIALITE],
            [TITRE],
            [NUM_LICENCE],
            [NUM_ORDRE],
            [DATE_OBTENTION_LICENCE],
            [DATE_EXPIRATION_LICENCE],
            [UNIVERSITE_FORMATION],
            [ANNEE_DIPLOME],
            [NUM_ADR],
            [TELEPHONE],
            [EMAIL],
            [CENTRE_PRATIQUE],
            [COD_CEN],
            [HONORAIRES],
            [LANGUE_PARLEE],
            [EXPERIENCE_ANNEE],
            [DISPONIBILITE],
            [ACTIF],
            [COD_CREUTIL],
            [COD_MODUTIL],
            [DAT_CREUTIL],
            [DAT_MODUTIL]
          FROM [hcs_backoffice].[core].[PRESTATAIRE]
          WHERE 1=1
        `;

        const request = pool.request();

        // Application des filtres selon le scope
        if (scope === 'active') {
          prestataireQuery += ` AND ACTIF = 1`;
        } else if (scope === 'recent') {
          const recentDate = new Date();
          recentDate.setDate(recentDate.getDate() - 7);
          prestataireQuery += ` AND (DAT_MODUTIL >= @recentDate OR DAT_CREUTIL >= @recentDate)`;
          request.input('recentDate', sql.DateTime, recentDate);
        } else if (scope === 'selected' && prestataireIds.length > 0) {
          const placeholders = prestataireIds.map((_, i) => `@cod_pre_${i}`).join(',');
          prestataireQuery += ` AND COD_PRE IN (${placeholders})`;
          prestataireIds.forEach((id, i) => {
            request.input(`cod_pre_${i}`, sql.VarChar(50), String(id));
          });
        }

        const prestataireResult = await request.query(prestataireQuery);
        statistics.totalProcessed += prestataireResult.recordset.length;

        // Traitement de chaque prestataire
        for (const prestataire of prestataireResult.recordset) {
          try {
            // Validation du COD_PRE
            if (!prestataire.COD_PRE) {
              console.error(`❌ COD_PRE manquant pour le prestataire:`, prestataire);
              syncResults.prestataires.push({
                cod_pre: 'unknown',
                status: 'error',
                error: 'COD_PRE manquant'
              });
              statistics.errors++;
              continue;
            }

            const codPreString = String(prestataire.COD_PRE).trim();

            // Synchronisation selon la direction
            if (direction === 'upload' || direction === 'bidirectional') {
              const updateQuery = `
                UPDATE [hcs_backoffice].[core].[PRESTATAIRE]
                SET 
                  COD_MODUTIL = @COD_MODUTIL,
                  DAT_MODUTIL = GETDATE()
                WHERE COD_PRE = @COD_PRE
              `;
              
              await pool.request()
                .input('COD_PRE', sql.VarChar(50), codPreString)
                .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system')
                .query(updateQuery);
            }

            syncResults.prestataires.push({
              cod_pre: codPreString,
              status: 'synced',
              direction: direction,
              details: {
                nom: prestataire.NOM_PRESTATAIRE,
                prenom: prestataire.PRENOM_PRESTATAIRE,
                centre_principal: prestataire.COD_CEN
              },
              timestamp: new Date().toISOString()
            });
            statistics.synced++;

          } catch (error) {
            console.error(`❌ Erreur synchronisation prestataire ${prestataire.COD_PRE}:`, error);
            syncResults.prestataires.push({
              cod_pre: prestataire.COD_PRE || 'unknown',
              status: 'error',
              error: error.message
            });
            statistics.errors++;
          }
        }
      } catch (error) {
        console.error('❌ Erreur récupération des prestataires:', error);
        syncResults.prestataires.push({
          status: 'error',
          error: `Erreur lors de la récupération des prestataires: ${error.message}`
        });
      }
    }

    // ==================== PHASE 3: SYNCHRONISATION DES CENTRES ====================
    if (entityTypes.includes('centre')) {
      try {
        let centreQuery = `
          SELECT TOP (${options.maxRecords}) 
            [COD_CEN],
            [COD_PAY],
            [COD_PAI],
            [LIB_CEN],
            [OBS_CEN],
            [ORD_CEN],
            [AUT_CEN],
            [NUM_ADR],
            [NUM_RIB],
            [ENR_CEN],
            [TR1_CEN],
            [TR2_CEN],
            [TR3_CEN],
            [TPS_CEN],
            [TVA_CEN],
            [DEB_AGR],
            [FIN_AGR],
            [DEB_CEN],
            [FIN_CEN],
            [BIO_CEN],
            [AGR_CEN],
            [COD_CREUTIL],
            [COD_MODUTIL],
            [DAT_CREUTIL],
            [DAT_MODUTIL],
            [TYP_CEN],
            [COD_TAR],
            [NCP_CEN],
            [PRM_CEN],
            [COD_NAT]
          FROM [hcs_backoffice].[core].[CENTRE]
          WHERE 1=1
        `;

        const request = pool.request();

        // Application des filtres
        if (scope === 'active') {
          centreQuery += ` AND ENR_CEN = 1`;
        } else if (scope === 'recent') {
          const recentDate = new Date();
          recentDate.setDate(recentDate.getDate() - 7);
          centreQuery += ` AND (DAT_MODUTIL >= @recentDate OR DAT_CREUTIL >= @recentDate)`;
          request.input('recentDate', sql.DateTime, recentDate);
        } else if (scope === 'selected' && centreIds.length > 0) {
          const placeholders = centreIds.map((_, i) => `@cod_cen_${i}`).join(',');
          centreQuery += ` AND COD_CEN IN (${placeholders})`;
          centreIds.forEach((id, i) => {
            request.input(`cod_cen_${i}`, sql.VarChar(50), String(id));
          });
        }

        const centreResult = await request.query(centreQuery);
        statistics.totalProcessed += centreResult.recordset.length;

        // Traitement de chaque centre
        for (const centre of centreResult.recordset) {
          try {
            // Vérifier que COD_CEN existe
            if (!centre.COD_CEN) {
              console.error(`❌ COD_CEN manquant pour le centre:`, centre);
              syncResults.centres.push({
                cod_cen: 'unknown',
                status: 'error',
                error: 'COD_CEN manquant'
              });
              statistics.errors++;
              continue;
            }

            const codCenString = String(centre.COD_CEN).trim();

            // Synchronisation selon la direction
            if (direction === 'upload' || direction === 'bidirectional') {
              const updateQuery = `
                UPDATE [hcs_backoffice].[core].[CENTRE]
                SET 
                  COD_MODUTIL = @COD_MODUTIL,
                  DAT_MODUTIL = GETDATE()
                WHERE COD_CEN = @COD_CEN
              `;
              
              await pool.request()
                .input('COD_CEN', sql.VarChar(50), codCenString)
                .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system')
                .query(updateQuery);
            }

            syncResults.centres.push({
              cod_cen: codCenString,
              status: 'synced',
              direction: direction,
              details: {
                libelle: centre.LIB_CEN,
                type: centre.TYP_CEN,
                pays: centre.COD_PAY
              },
              timestamp: new Date().toISOString()
            });
            statistics.synced++;

          } catch (error) {
            console.error(`❌ Erreur synchronisation centre ${centre.COD_CEN}:`, error);
            syncResults.centres.push({
              cod_cen: centre.COD_CEN || 'unknown',
              status: 'error',
              error: error.message
            });
            statistics.errors++;
          }
        }
      } catch (error) {
        console.error('❌ Erreur récupération des centres:', error);
        syncResults.centres.push({
          status: 'error',
          error: `Erreur lors de la récupération des centres: ${error.message}`
        });
      }
    }

    // ==================== PHASE 4: SYNCHRONISATION DES ASSOCIATIONS EXISTANTES ====================
    if (options.includeAssociations && entityTypes.includes('prestataire') && entityTypes.includes('centre')) {
      try {
        let associationQuery = `
          SELECT TOP (${options.maxRecords}) 
            [NUM_PRECEN],
            [COD_PAY],
            [COD_PRE],
            [COD_CEN],
            [DEB_AGRP],
            [FIN_AGRP],
            [OBS_AGRP],
            [TR1_AGRP],
            [TR2_AGRP],
            [TR3_AGRP],
            [TPS_AGRP],
            [TVA_AGRP],
            [COD_CREUTIL],
            [COD_MODUTIL],
            [DAT_CREUTIL],
            [DAT_MODUTIL]
          FROM [hcs_backoffice].[core].[CENTRE_PRESTATAIRE]
          WHERE 1=1
        `;

        const request = pool.request();
        const whereConditions = [];
        
        if (prestataireIds.length > 0) {
          const placeholders = prestataireIds.map((_, i) => `@cod_pre_${i}`).join(',');
          whereConditions.push(`COD_PRE IN (${placeholders})`);
          prestataireIds.forEach((id, i) => {
            request.input(`cod_pre_${i}`, sql.VarChar(50), String(id));
          });
        }
        
        if (centreIds.length > 0) {
          const placeholders = centreIds.map((_, i) => `@cod_cen_${i}`).join(',');
          whereConditions.push(`COD_CEN IN (${placeholders})`);
          centreIds.forEach((id, i) => {
            request.input(`cod_cen_${i}`, sql.VarChar(50), String(id));
          });
        }
        
        if (scope === 'recent') {
          const recentDate = new Date();
          recentDate.setDate(recentDate.getDate() - 7);
          whereConditions.push(`(DAT_MODUTIL >= @recentDate OR DAT_CREUTIL >= @recentDate)`);
          request.input('recentDate', sql.DateTime, recentDate);
        }
        
        if (whereConditions.length > 0) {
          associationQuery += ` AND (${whereConditions.join(' OR ')})`;
        }

        const associationResult = await request.query(associationQuery);
        statistics.totalProcessed += associationResult.recordset.length;

        // Traitement de chaque association
        for (const association of associationResult.recordset) {
          try {
            // Vérifier que les codes existent
            if (!association.COD_PRE || !association.COD_CEN) {
              console.error(`❌ Données manquantes pour l'association ${association.NUM_PRECEN}:`, association);
              syncResults.associations.push({
                num_precen: association.NUM_PRECEN,
                status: 'error',
                error: 'COD_PRE ou COD_CEN manquant'
              });
              statistics.errors++;
              continue;
            }

            // Mise à jour des métadonnées
            const updateQuery = `
              UPDATE [hcs_backoffice].[core].[CENTRE_PRESTATAIRE]
              SET 
                COD_MODUTIL = @COD_MODUTIL,
                DAT_MODUTIL = GETDATE()
              WHERE NUM_PRECEN = @NUM_PRECEN
            `;
            
            await pool.request()
              .input('NUM_PRECEN', sql.Int, association.NUM_PRECEN)
              .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system')
              .query(updateQuery);

            syncResults.associations.push({
              num_precen: association.NUM_PRECEN,
              status: 'synced',
              details: {
                cod_pre: String(association.COD_PRE),
                cod_cen: String(association.COD_CEN),
                periode: {
                  debut: association.DEB_AGRP,
                  fin: association.FIN_AGRP
                }
              },
              timestamp: new Date().toISOString()
            });
            statistics.synced++;

          } catch (error) {
            console.error(`❌ Erreur synchronisation association ${association.NUM_PRECEN}:`, error);
            syncResults.associations.push({
              num_precen: association.NUM_PRECEN,
              status: 'error',
              error: error.message
            });
            statistics.errors++;
          }
        }
      } catch (error) {
        console.error('❌ Erreur récupération des associations:', error);
        syncResults.associations.push({
          status: 'error',
          error: `Erreur lors de la récupération des associations: ${error.message}`
        });
      }
    }

    // ==================== PHASE 5: REMPLISSAGE DES ASSOCIATIONS MANQUANTES ====================
    if (options.fillMissingAssociations && entityTypes.includes('prestataire') && entityTypes.includes('centre')) {
      try {
        console.log('🔄 Début du remplissage des associations manquantes...');
        
        // Récupérer les prestataires avec centre principal VALIDE (qui existe dans la table CENTRE)
        const validPrestatairesQuery = `
          SELECT DISTINCT
            p.COD_PRE,
            p.COD_PAY,
            p.COD_CEN,
            p.COD_CREUTIL,
            p.COD_MODUTIL,
            c.TR1_CEN,
            c.TR2_CEN,
            c.TR3_CEN,
            c.TPS_CEN,
            c.TVA_CEN,
            p.NOM_PRESTATAIRE,
            p.PRENOM_PRESTATAIRE,
            c.LIB_CEN
          FROM [hcs_backoffice].[core].[PRESTATAIRE] p
          INNER JOIN [hcs_backoffice].[core].[CENTRE] c ON p.COD_CEN = c.COD_CEN
          WHERE p.COD_CEN IS NOT NULL 
            AND p.COD_CEN != ''
            AND TRIM(p.COD_CEN) != ''
            AND c.COD_CEN IS NOT NULL
        `;

        // Appliquer les filtres selon le scope
        let finalQuery = validPrestatairesQuery;
        const request = pool.request();
        
        if (scope === 'active') {
          finalQuery += ` AND p.ACTIF = 1`;
        } else if (scope === 'selected' && prestataireIds.length > 0) {
          const placeholders = prestataireIds.map((_, i) => `@cod_pre_${i}`).join(',');
          finalQuery += ` AND p.COD_PRE IN (${placeholders})`;
          prestataireIds.forEach((id, i) => {
            request.input(`cod_pre_${i}`, sql.VarChar(50), String(id));
          });
        }

        const validPrestatairesResult = await request.query(finalQuery);
        
        console.log(`📊 ${validPrestatairesResult.recordset.length} prestataires avec centre principal valide trouvés`);

        // Pour chaque prestataire, créer l'association si elle n'existe pas
        for (const prestataire of validPrestatairesResult.recordset) {
          try {
            const codPreString = String(prestataire.COD_PRE).trim();
            const codCenString = String(prestataire.COD_CEN).trim();

            // Validation supplémentaire
            if (!codPreString || codPreString === '') {
              console.warn(`⚠️ COD_PRE vide ou invalide pour le prestataire:`, prestataire);
              continue;
            }

            if (!codCenString || codCenString === '') {
              console.warn(`⚠️ COD_CEN vide ou invalide pour le prestataire ${codPreString}`);
              continue;
            }

            // Vérifier si l'association existe déjà
            const checkAssociationQuery = `
              SELECT COUNT(*) as count, MAX(NUM_PRECEN) as num_precen
              FROM [hcs_backoffice].[core].[CENTRE_PRESTATAIRE]
              WHERE COD_PRE = @COD_PRE AND COD_CEN = @COD_CEN
            `;

            const checkResult = await pool.request()
              .input('COD_PRE', sql.VarChar(50), codPreString)
              .input('COD_CEN', sql.VarChar(50), codCenString)
              .query(checkAssociationQuery);

            if (checkResult.recordset[0].count > 0) {
              // L'association existe déjà
              console.log(`✓ Association déjà existante: ${codPreString} -> ${codCenString} (ID: ${checkResult.recordset[0].num_precen})`);
              continue;
            }

            // Créer l'association manquante
            const insertQuery = `
              INSERT INTO [hcs_backoffice].[core].[CENTRE_PRESTATAIRE] (
                [COD_PAY],
                [COD_PRE],
                [COD_CEN],
                [DEB_AGRP],
                [FIN_AGRP],
                [OBS_AGRP],
                [TR1_AGRP],
                [TR2_AGRP],
                [TR3_AGRP],
                [TPS_AGRP],
                [TVA_AGRP],
                [COD_CREUTIL],
                [COD_MODUTIL],
                [DAT_CREUTIL],
                [DAT_MODUTIL]
              ) VALUES (
                @COD_PAY,
                @COD_PRE,
                @COD_CEN,
                @DEB_AGRP,
                @FIN_AGRP,
                @OBS_AGRP,
                @TR1_AGRP,
                @TR2_AGRP,
                @TR3_AGRP,
                @TPS_AGRP,
                @TVA_AGRP,
                @COD_CREUTIL,
                @COD_MODUTIL,
                GETDATE(),
                GETDATE()
              );
              
              SELECT SCOPE_IDENTITY() as new_id;
            `;

            // Préparer les valeurs
            const now = new Date();
            const defaultStartDate = options.defaultAssociationDates ? now : null;
            const defaultEndDate = options.defaultAssociationDates ? 
              new Date(now.getFullYear() + 1, now.getMonth(), now.getDate()) : null;

            const insertRequest = pool.request()
              .input('COD_PAY', sql.VarChar(50), prestataire.COD_PAY || '')
              .input('COD_PRE', sql.VarChar(50), codPreString)
              .input('COD_CEN', sql.VarChar(50), codCenString)
              .input('DEB_AGRP', sql.DateTime, defaultStartDate)
              .input('FIN_AGRP', sql.DateTime, defaultEndDate)
              .input('OBS_AGRP', sql.VarChar(sql.MAX), `Association créée automatiquement pour ${prestataire.PRENOM_PRESTATAIRE} ${prestataire.NOM_PRESTATAIRE} avec ${prestataire.LIB_CEN} le ${now.toISOString()}`)
              .input('COD_CREUTIL', sql.VarChar(50), req.user?.username || 'system')
              .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system');

            // Copier les taxes du centre si l'option est activée
            if (options.syncTaxesFromCentre && prestataire.TR1_CEN !== undefined) {
              insertRequest
                .input('TR1_AGRP', sql.Decimal(18, 2), prestataire.TR1_CEN || 0)
                .input('TR2_AGRP', sql.Decimal(18, 2), prestataire.TR2_CEN || 0)
                .input('TR3_AGRP', sql.Decimal(18, 2), prestataire.TR3_CEN || 0)
                .input('TPS_AGRP', sql.Decimal(18, 2), prestataire.TPS_CEN || 0)
                .input('TVA_AGRP', sql.Decimal(18, 2), prestataire.TVA_CEN || 0);
            } else {
              insertRequest
                .input('TR1_AGRP', sql.Decimal(18, 2), 0)
                .input('TR2_AGRP', sql.Decimal(18, 2), 0)
                .input('TR3_AGRP', sql.Decimal(18, 2), 0)
                .input('TPS_AGRP', sql.Decimal(18, 2), 0)
                .input('TVA_AGRP', sql.Decimal(18, 2), 0);
            }

            const insertResult = await insertRequest.query(insertQuery);
            const newAssociationId = insertResult.recordset[0]?.new_id;

            syncResults.fillOperations.push({
              status: 'created',
              type: 'association',
              details: {
                num_precen: newAssociationId,
                cod_pre: codPreString,
                cod_cen: codCenString,
                prestataire: `${prestataire.PRENOM_PRESTATAIRE} ${prestataire.NOM_PRESTATAIRE}`,
                centre: prestataire.LIB_CEN,
                source: 'automatic_fill',
                taxes_copied: options.syncTaxesFromCentre
              },
              timestamp: new Date().toISOString()
            });

            statistics.associationsCreated++;
            console.log(`✅ Association créée: ${codPreString} -> ${codCenString} (ID: ${newAssociationId})`);

          } catch (error) {
            console.error(`❌ Erreur création association pour ${prestataire.COD_PRE}:`, error);
            
            // Log détaillé en cas d'erreur FK
            if (error.number === 547) {
              console.error(`🔍 Erreur FK - Prestataire: ${prestataire.COD_PRE}, Centre: ${prestataire.COD_CEN}`);
            }
            
            syncResults.fillOperations.push({
              status: 'error',
              type: 'association',
              details: {
                cod_pre: prestataire.COD_PRE,
                cod_cen: prestataire.COD_CEN,
                error: error.message,
                errorCode: error.number
              }
            });
            statistics.errors++;
          }
        }

        // Mise à jour des taxes des associations existantes
        if (options.syncTaxesFromCentre) {
          try {
            console.log('🔄 Mise à jour des taxes des associations existantes...');
            
            const updateTaxesQuery = `
              UPDATE cp
              SET 
                cp.TR1_AGRP = ISNULL(c.TR1_CEN, cp.TR1_AGRP),
                cp.TR2_AGRP = ISNULL(c.TR2_CEN, cp.TR2_AGRP),
                cp.TR3_AGRP = ISNULL(c.TR3_CEN, cp.TR3_AGRP),
                cp.TPS_AGRP = ISNULL(c.TPS_CEN, cp.TPS_AGRP),
                cp.TVA_AGRP = ISNULL(c.TVA_CEN, cp.TVA_AGRP),
                cp.COD_MODUTIL = @COD_MODUTIL,
                cp.DAT_MODUTIL = GETDATE()
              FROM [hcs_backoffice].[core].[CENTRE_PRESTATAIRE] cp
              INNER JOIN [hcs_backoffice].[core].[CENTRE] c ON cp.COD_CEN = c.COD_CEN
              WHERE cp.COD_CEN IS NOT NULL
            `;

            const updateResult = await pool.request()
              .input('COD_MODUTIL', sql.VarChar(50), req.user?.username || 'system')
              .query(updateTaxesQuery);

            statistics.associationsUpdated = updateResult.rowsAffected[0] || 0;
            
            console.log(`✅ ${statistics.associationsUpdated} associations mises à jour avec les taxes du centre`);
            
            syncResults.fillOperations.push({
              status: 'updated',
              type: 'taxes_update',
              details: {
                count: statistics.associationsUpdated,
                message: `Taxes mises à jour pour ${statistics.associationsUpdated} associations`
              }
            });

          } catch (error) {
            console.error('❌ Erreur mise à jour des taxes:', error);
            syncResults.fillOperations.push({
              status: 'error',
              type: 'taxes_update',
              error: error.message
            });
          }
        }

        console.log(`🎉 Remplissage terminé: ${statistics.associationsCreated} associations créées, ${statistics.associationsUpdated} mises à jour`);

      } catch (error) {
        console.error('❌ Erreur lors du remplissage des associations:', error);
        syncResults.fillOperations.push({
          status: 'error',
          type: 'fill_process',
          error: error.message
        });
      }
    }

    // ==================== PHASE 6: SAUVEGARDE ====================
    let backupInfo = null;
    if (options.createBackup && (statistics.synced > 0 || statistics.associationsCreated > 0)) {
      try {
        const backupTimestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const backupTableName = `BACKUP_SYNC_${backupTimestamp}`;
        
        const createBackupQuery = `
          SELECT * INTO [hcs_backoffice].[backup].[${backupTableName}]
          FROM (
            SELECT 
              'prestataire' as entity_type,
              COD_PRE as entity_id,
              DAT_MODUTIL as last_sync,
              GETDATE() as backup_date
            FROM [hcs_backoffice].[core].[PRESTATAIRE]
            WHERE DAT_MODUTIL > DATEADD(minute, -5, GETDATE())
            
            UNION ALL
            
            SELECT 
              'centre' as entity_type,
              COD_CEN as entity_id,
              DAT_MODUTIL as last_sync,
              GETDATE() as backup_date
            FROM [hcs_backoffice].[core].[CENTRE]
            WHERE DAT_MODUTIL > DATEADD(minute, -5, GETDATE())
            
            UNION ALL
            
            SELECT 
              'association' as entity_type,
              CAST(NUM_PRECEN as varchar) as entity_id,
              DAT_MODUTIL as last_sync,
              GETDATE() as backup_date
            FROM [hcs_backoffice].[core].[CENTRE_PRESTATAIRE]
            WHERE DAT_MODUTIL > DATEADD(minute, -5, GETDATE())
          ) as sync_data
        `;
        
        await pool.request().query(createBackupQuery);
        
        backupInfo = {
          success: true,
          message: 'Backup créé avec succès',
          table_name: backupTableName,
          records_backed_up: statistics.synced + statistics.associationsCreated
        };
      } catch (backupError) {
        console.error('⚠️ Erreur création backup:', backupError.message);
        backupInfo = {
          success: false,
          error: backupError.message
        };
      }
    }

    // ==================== PHASE 7: NOTIFICATION ====================
    if (options.notifyUsers && req.user?.email) {
      try {
        await sendSyncNotification(req.user.email, {
          statistics,
          syncResults,
          scope,
          direction,
          entityTypes
        });
      } catch (notificationError) {
        console.error('⚠️ Erreur envoi notification:', notificationError.message);
      }
    }

    // ==================== PHASE 8: PRÉPARATION DE LA RÉPONSE ====================
    const successRate = statistics.totalProcessed > 0 
      ? ((statistics.synced / statistics.totalProcessed) * 100).toFixed(2)
      : 0;

    const response = {
      success: statistics.errors === 0 || options.forceUpdate,
      data: {
        metadata: {
          timestamp: new Date().toISOString(),
          user: req.user?.username || 'system',
          scope,
          direction,
          entityTypes,
          options
        },
        statistics: {
          ...statistics,
          successRate: `${successRate}%`,
          details: {
            prestataires: syncResults.prestataires.length,
            centres: syncResults.centres.length,
            associations: syncResults.associations.length,
            fillOperations: syncResults.fillOperations.length,
            validationErrors: statistics.validationErrors
          }
        },
        results: {
          prestataires: syncResults.prestataires.slice(0, 50),
          centres: syncResults.centres.slice(0, 50),
          associations: syncResults.associations.slice(0, 50),
          fillOperations: syncResults.fillOperations
        },
        summary: {
          message: `Synchronisation terminée. ${statistics.synced} entités synchronisées, ${statistics.errors} erreurs, ${statistics.associationsCreated} associations créées, ${statistics.associationsUpdated} associations mises à jour.`,
          status: statistics.errors === 0 ? 'completed_successfully' : 
                  (options.forceUpdate ? 'completed_with_errors' : 'partially_completed')
        },
        backup: backupInfo,
        fillSummary: {
          associationsCreated: statistics.associationsCreated,
          associationsUpdated: statistics.associationsUpdated,
          totalAssociations: statistics.associationsCreated + statistics.associationsUpdated
        }
      }
    };

    // Ajouter les erreurs de validation si elles existent
    if (statistics.validationErrors > 0) {
      response.data.validation = syncResults.validation;
    }

    return res.json(response);

  } catch (error) {
    console.error('❌ Erreur synchronisation globale:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur serveur lors de la synchronisation globale',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined,
      timestamp: new Date().toISOString()
    });
  } finally {
    if (pool) {
      try {
        await pool.close();
      } catch (closeError) {
        console.error('❌ Erreur fermeture connexion:', closeError);
      }
    }
  }
});

