// POST - Créer un nouveau barème
app.post('/api/baremes', authenticateToken, async (req, res) => {
  try {
    const pool = await dbConfig.getConnection();
    const {
      COD_BAR,
      COD_PAY,
      LIB_BAR,
      TYP_BAR,
      COD_CREUTIL
    } = req.body;

    // Validation des données requises
    if (!LIB_BAR) {
      return res.status(400).json({
        success: false,
        message: 'Le nom du barème est obligatoire'
      });
    }

    // Générer un COD_BAR si non fourni
    const codBar = COD_BAR || Math.floor(Math.random() * 9000) + 1000;

    const query = `
      INSERT INTO [hcs_backoffice].[metier].[CODE_BAREME] (
        COD_BAR,
        COD_PAY,
        LIB_BAR,
        TYP_BAR,
        COD_CREUTIL,
        DAT_CREUTIL
      ) VALUES (
        @cod_bar,
        @cod_pay,
        @lib_bar,
        @type_bareme,
        @cod_creutil,
        GETDATE()
      );
      
      SELECT @cod_bar as new_id;
    `;

    const request = pool.request();
    request.input('cod_bar', sql.Int, codBar);
    request.input('cod_pay', sql.VarChar(3), COD_PAY || 'SN');
    request.input('lib_bar', sql.VarChar(64), LIB_BAR);
    request.input('type_bareme', sql.Int, TYP_BAR || 0);
    request.input('cod_creutil', sql.VarChar(16), COD_CREUTIL || 'SYSTEM');

    await request.query(query);

    return res.json({
      success: true,
      message: 'Barème créé avec succès',
      id: codBar
    });

  } catch (error) {
    console.error('❌ Erreur création barème:', error);
    
    // Gestion spécifique des erreurs de duplication
    if (error.message && error.message.includes('duplicate')) {
      return res.status(400).json({
        success: false,
        message: 'Un barème avec ce code existe déjà'
      });
    }

    return res.status(500).json({
      success: false,
      message: 'Erreur lors de la création du barème',
      error: error.message
    });
  }
});

