// ROUTES DES POLICES D'ASSURANCE
// ==============================================
// Route pour récupérer les compagnies d'assurance
app.get('/api/polices/compagnies', authenticateToken, async (req, res) => {
  try {
    const pool = await dbConfig.getConnection();
    
    const query = `
      SELECT 
        c.COD_ASS as id,
        c.COD_ASS,
        c.LIB_ASS as nom,
        c.COD_PAY,
        c.COD_STA,
        c.NUM_ADR,
        c.AUT_ASS,
        c.EMA_ASS,
        c.COD_RES,
        c.COD_TAR,
        c.COD_BAR,
        c.COD_PAI,
        c.NUM_RIB,
        c.OBS_ASS,
        c.GEN_ASS,
        c.COD_CREUTIL,
        c.COD_MODUTIL,
        c.DAT_CREUTIL,
        c.DAT_MODUTIL,
        ta.LIB_STA as type_assureur,
        p.LIB_PAY as pays,
        -- Calcul du statut actif (basé sur GEN_ASS)
        CASE 
          WHEN c.GEN_ASS = 1 OR c.GEN_ASS = '1' THEN 1
          ELSE 0
        END as actif,
        -- Nom complet pour l'affichage
        CONCAT(c.LIB_ASS, ' (', ISNULL(ta.LIB_STA, 'N/A'), ')') as nom_complet
      FROM [core].[COMPAGNIE] c
      LEFT JOIN [ref].[TYPE_ASSUREUR] ta ON c.COD_STA = ta.COD_STA
      LEFT JOIN [ref].[PAYS] p ON c.COD_PAY = p.COD_PAY
      WHERE (c.GEN_ASS = 1 OR c.GEN_ASS = '1' OR c.GEN_ASS IS NULL OR c.GEN_ASS = 0)
      ORDER BY c.LIB_ASS
    `;
    
    const result = await pool.request().query(query);
    
    // Formater la réponse pour le frontend
    const compagnies = result.recordset.map(compagnie => ({
      id: compagnie.id,
      COD_ASS: compagnie.COD_ASS,
      nom: compagnie.nom,
      LIB_ASS: compagnie.nom,
      NOM_COMPAGNIE: compagnie.nom, // Pour la compatibilité avec le frontend
      type_assureur: compagnie.type_assureur,
      COD_STA: compagnie.COD_STA,
      email: compagnie.EMA_ASS,
      telephone: compagnie.NUM_ADR, // NUM_ADR contient probablement le téléphone
      adresse: compagnie.NUM_ADR, // À vérifier si c'est bien l'adresse
      pays: compagnie.pays,
      COD_PAY: compagnie.COD_PAY,
      actif: compagnie.actif,
      observations: compagnie.OBS_ASS,
      nom_complet: compagnie.nom_complet
    }));
    
    return res.json({
      success: true,
      message: `${compagnies.length} compagnie(s) trouvée(s)`,
      compagnies: compagnies,
      timestamp: new Date().toISOString()
    });
    
  } catch (error) {
    console.error('❌ Erreur récupération compagnies:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur lors de la récupération des compagnies',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined,
      timestamp: new Date().toISOString()
    });
  }
});

