// Route pour récupérer les types de police (basés sur les valeurs distinctes de la table POLICE)
app.get('/api/polices/types', authenticateToken, async (req, res) => {
  try {
    const pool = await dbConfig.getConnection();
    
    // Option 1: Si vous avez une table de référence pour les types de police
    let typesResult;
    
    try {
      // Essayez d'abord de récupérer depuis une table de référence
      const refQuery = `
        SELECT 
          COD_TYP as value,
          LIB_TYP as label
        FROM [ref].[TYPE_POLICE]
        ORDER BY LIB_TYP
      `;
      typesResult = await pool.request().query(refQuery);
    } catch (error) {
      console.log('Table TYPE_POLICE non trouvée, utilisation des valeurs distinctes');
      
      // Option 2: Récupérer les valeurs distinctes de TYP_POL dans la table POLICE
      const distinctQuery = `
        SELECT DISTINCT
          TYP_POL as value,
          CASE TYP_POL
            WHEN 'I' THEN 'Individuelle'
            WHEN 'C' THEN 'Collective'
            WHEN 'G' THEN 'Groupe'
            WHEN 'F' THEN 'Familiale'
            WHEN 'E' THEN 'Entreprise'
            WHEN 'A' THEN 'Auto'
            WHEN 'H' THEN 'Habitation'
            WHEN 'S' THEN 'Santé'
            WHEN 'V' THEN 'Vie'
            WHEN 'R' THEN 'Risques divers'
            ELSE TYP_POL
          END as label
        FROM [core].[POLICE]
        WHERE TYP_POL IS NOT NULL AND TYP_POL != ''
        ORDER BY label
      `;
      
      typesResult = await pool.request().query(distinctQuery);
    }
    
    // Si toujours vide, retourner des valeurs par défaut
    let types = typesResult.recordset;
    if (types.length === 0) {
      types = [
        { value: 'I', label: 'Individuelle' },
        { value: 'C', label: 'Collective' },
        { value: 'G', label: 'Groupe' },
        { value: 'F', label: 'Familiale' },
        { value: 'E', label: 'Entreprise' },
        { value: 'S', label: 'Santé' }
      ];
    }
    
    return res.json({
      success: true,
      message: `${types.length} type(s) de police trouvé(s)`,
      types: types,
      timestamp: new Date().toISOString()
    });
    
  } catch (error) {
    console.error('❌ Erreur récupération types police:', error);
    
    // Fallback avec des données par défaut
    return res.json({
      success: true,
      message: 'Types de police récupérés (données par défaut)',
      types: [
        { value: 'I', label: 'Individuelle' },
        { value: 'C', label: 'Collective' },
        { value: 'G', label: 'Groupe' },
        { value: 'F', label: 'Familiale' },
        { value: 'E', label: 'Entreprise' },
        { value: 'S', label: 'Santé' }
      ],
      timestamp: new Date().toISOString()
    });
  }
});

// Route pour récupérer les polices d'un bénéficiaire
app.get('/api/polices/beneficiaire/:beneficiaireId', authenticateToken, async (req, res) => {
  try {
    const { beneficiaireId } = req.params;
    
    if (!beneficiaireId || isNaN(parseInt(beneficiaireId))) {
      return res.status(400).json({
        success: false,
        message: 'ID bénéficiaire invalide'
      });
    }
    
    console.log(`📋 Récupération des polices pour bénéficiaire ${beneficiaireId}...`);
    const pool = await dbConfig.getConnection();
    
    const query = `
      SELECT 
        bp.NUM_BPO,
        bp.COD_BEN,
        bp.COD_POL,
        bp.COD_BPO,
        bp.ENT_BPO,
        bp.STE_BPO,
        bp.SOR_BPO,
        bp.STS_BPO,
        bp.MAT_BPO,
        bp.MAC_BPO,
        bp.PLF_BPO,
        bp.SUS_BPO,
        bp.REM_BPO,
        bp.DAT_DEME,
        bp.DAT_DEMS,
        bp.COD_PAY,
        p.NUM_POL,
        p.EFF_POL,
        p.RES_POL,
        p.STD_POL,
        p.REM_POL as REMARQUE_POLICE,
        p.TXA_POL,
        p.TXH_POL,
        p.IND_POL,
        c.LIB_ASS as NOM_COMPAGNIE, -- Utiliser LIB_ASS au lieu de NOM_COMPAGNIE
        s.LIB_SOU as NOM_SOUSCRIPTEUR, -- Utiliser LIB_SOU
        -- Calcul du statut
        CASE 
          WHEN p.RES_POL IS NOT NULL AND p.RES_POL < GETDATE() THEN 'Résiliée'
          WHEN p.SUS_POL IS NOT NULL AND p.SUS_POL < GETDATE() THEN 'Suspendue'
          WHEN p.EFF_POL IS NOT NULL AND p.EFF_POL > GETDATE() THEN 'En attente'
          WHEN p.STD_POL = 1 THEN 'Active'
          ELSE 'Inactive'
        END as status_display,
        -- Statut du bénéficiaire dans la police
        CASE 
          WHEN bp.STS_BPO = 'A' THEN 'Actif'
          WHEN bp.STS_BPO = 'S' THEN 'Suspendu'
          WHEN bp.STS_BPO = 'R' THEN 'Résilié'
          ELSE bp.STS_BPO
        END as statut_beneficiaire
      FROM [core].[BENEF_POLICE] bp
      INNER JOIN [core].[POLICE] p ON bp.COD_POL = p.COD_POL
      LEFT JOIN [core].[COMPAGNIE] c ON p.COD_ASS = c.COD_ASS
      LEFT JOIN [core].[SOUSCRIPTEUR] s ON p.COD_SOU = s.COD_SOU
      WHERE bp.COD_BEN = @beneficiaireId
      ORDER BY p.EFF_POL DESC
    `;
    
    const result = await pool.request()
      .input('beneficiaireId', sql.Int, parseInt(beneficiaireId))
      .query(query);
    
    return res.json({
      success: true,
      message: `${result.recordset.length} police(s) trouvée(s) pour ce bénéficiaire`,
      polices: result.recordset,
      timestamp: new Date().toISOString()
    });
    
  } catch (error) {
    console.error(`❌ Erreur polices bénéficiaire ${req.params.beneficiaireId}:`, error);
    return res.status(500).json({
      success: false,
      message: 'Erreur lors de la récupération des polices du bénéficiaire',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined,
      timestamp: new Date().toISOString()
    });
  }
});


// Route pour récupérer toutes les polices avec pagination et filtres
app.get('/api/polices', authenticateToken, async (req, res) => {
  try {
    const { 
      page = 1, 
      limit = 20, 
      search, 
      status, 
      compagnie,
      sortBy = 'COD_POL',
      sortOrder = 'DESC'
    } = req.query;
    
    const offset = (parseInt(page) - 1) * parseInt(limit);
    
    console.log(`📋 Récupération des polices avec filtres:`, { 
      page, limit, search, status, compagnie 
    });
    
    const pool = await dbConfig.getConnection();
    
    // Construction de la requête de base
    let whereClause = 'WHERE 1=1';
    let params = [];
    
    if (search) {
      whereClause += ` AND (p.NUM_POL LIKE @search OR p.NUMR_POL LIKE @search OR p.ORD_POL LIKE @search)`;
      params.push({ name: 'search', value: `%${search}%` });
    }
    
    if (status) {
      whereClause += ` AND p.STD_POL = @status`;
      params.push({ name: 'status', value: status === '1' ? 1 : 0 });
    }
    
    if (compagnie && !isNaN(parseInt(compagnie))) {
      whereClause += ` AND p.COD_ASS = @compagnie`;
      params.push({ name: 'compagnie', value: parseInt(compagnie) });
    }
    
    // Récupération des polices
    const policesQuery = `
      SELECT 
        p.COD_POL as id,
        p.NUM_POL,
        p.NUMR_POL,
        p.ORD_POL,
        p.EFF_POL,
        p.RES_POL,
        p.EMP_POL,
        p.BIO_POL,
        p.PEC_POL,
        p.STD_POL,
        p.REM_POL,
        p.COG_POL,
        p.COP_POL,
        p.PRM_POL,
        p.EMA_POL,
        p.NAT_POL,
        p.TYP_POL,
        p.TYC_POL,
        p.IND_POL,
        p.DEM_POL,
        p.SUS_POL,
        p.VIG_POL,
        p.RSP_POL,
        p.TXA_POL,
        p.TXH_POL,
        p.AUT_POL,
        p.MAJAUT_POL,
        p.AGEAUT_POL,
        p.DEL_POL,
        p.TTM_POL,
        p.TPL_POL,
        p.COM_POL,
        p.OBS_POL,
        p.DAT_CSS,
        p.MOD_POL,
        p.COD_CAR,
        p.MOD_CAR,
        p.PMT_POL,
        p.COD_ASS,
        p.COD_SOU,
        p.COD_INT,
        p.COD_CNV,
        p.COD_RES,
        p.COD_TAR,
        p.COD_BAR,
        p.COD_PAI,
        p.COD_PYR,
        p.COD_PAY,
        p.COD_CREUTIL,
        p.COD_MODUTIL,
        p.DAT_CREUTIL,
        p.DAT_MODUTIL,
        c.LIB_ASS as NOM_COMPAGNIE, -- Correction ici
        s.LIB_SOU as NOM_SOUSCRIPTEUR, -- Correction ici
        -- Calcul du statut
        CASE 
          WHEN p.RES_POL IS NOT NULL AND p.RES_POL < GETDATE() THEN 'Résiliée'
          WHEN p.SUS_POL IS NOT NULL AND p.SUS_POL < GETDATE() THEN 'Suspendue'
          WHEN p.EFF_POL IS NOT NULL AND p.EFF_POL > GETDATE() THEN 'En attente'
          WHEN p.STD_POL = 1 THEN 'Active'
          ELSE 'Inactive'
        END as status_display,
        -- Nombre de bénéficiaires
        (SELECT COUNT(*) FROM [core].[BENEF_POLICE] bp WHERE bp.COD_POL = p.COD_POL) as nb_beneficiaires
      FROM [core].[POLICE] p
      LEFT JOIN [core].[COMPAGNIE] c ON p.COD_ASS = c.COD_ASS
      LEFT JOIN [core].[SOUSCRIPTEUR] s ON p.COD_SOU = s.COD_SOU
      ${whereClause}
      ORDER BY p.${sortBy} ${sortOrder}
      OFFSET ${offset} ROWS FETCH NEXT ${parseInt(limit)} ROWS ONLY
    `;
    
    const policesResult = await pool.request();
    params.forEach(param => {
      policesResult.input(param.name, param.value);
    });
    const polices = await policesResult.query(policesQuery);
    
    // Récupération du nombre total
    const countQuery = `
      SELECT COUNT(*) as total
      FROM [core].[POLICE] p
      ${whereClause}
    `;
    
    const countResult = await pool.request();
    params.forEach(param => {
      countResult.input(param.name, param.value);
    });
    const totalResult = await countResult.query(countQuery);
    const total = totalResult.recordset[0].total;
    
    return res.json({
      success: true,
      message: `${polices.recordset.length} police(s) trouvée(s)`,
      polices: polices.recordset,
      pagination: {
        total: parseInt(total),
        page: parseInt(page),
        limit: parseInt(limit),
        totalPages: Math.ceil(total / parseInt(limit))
      },
      timestamp: new Date().toISOString()
    });
    
  } catch (error) {
    console.error('❌ Erreur récupération polices:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur lors de la récupération des polices',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined,
      timestamp: new Date().toISOString()
    });
  }
});


// Route pour récupérer une police par son ID
app.get('/api/polices/:id', authenticateToken, async (req, res) => {
  try {
    const { id } = req.params;
    
    if (!id || isNaN(parseInt(id))) {
      return res.status(400).json({
        success: false,
        message: 'ID police invalide'
      });
    }
    
    console.log(`📋 Récupération détaillée police ${id}...`);
    const pool = await dbConfig.getConnection();
    
    // 1. RÉCUPÉRER LES INFORMATIONS DE LA POLICE
    const policeQuery = `
      SELECT 
        p.COD_POL,
        p.NUM_POL,
        p.NUMR_POL,
        p.ORD_POL,
        p.EFF_POL,
        p.RES_POL,
        p.EMP_POL,
        p.BIO_POL,
        p.PEC_POL,
        p.STD_POL,
        p.REM_POL,
        p.COG_POL,
        p.COP_POL,
        p.PRM_POL,
        p.EMA_POL,
        p.NAT_POL,
        p.TYP_POL,
        p.TYC_POL,
        p.IND_POL,
        p.DEM_POL,
        p.SUS_POL,
        p.VIG_POL,
        p.RSP_POL,
        p.TXA_POL,
        p.TXH_POL,
        p.AUT_POL,
        p.MAJAUT_POL,
        p.AGEAUT_POL,
        p.DEL_POL,
        p.TTM_POL,
        p.TPL_POL,
        p.COM_POL,
        p.OBS_POL,
        p.DAT_CSS,
        p.MOD_POL,
        p.COD_CAR,
        p.MOD_CAR,
        p.PMT_POL,
        p.COD_ASS,
        p.COD_SOU,
        p.COD_INT,
        p.COD_CNV,
        p.COD_RES,
        p.COD_TAR,
        p.COD_BAR,
        p.COD_PAI,
        p.COD_PYR,
        p.COD_PAY,
        p.COD_CREUTIL,
        p.COD_MODUTIL,
        p.DAT_CREUTIL,
        p.DAT_MODUTIL,
        c.LIB_ASS as NOM_COMPAGNIE,
        c.NUM_ADR as ADRESSE_COMPAGNIE,
        c.NUM_ADR as TELEPHONE_COMPAGNIE,
        c.EMA_ASS as EMAIL_COMPAGNIE,
        s.LIB_SOU as NOM_SOUSCRIPTEUR,
        -- Calcul du statut
        CASE 
          WHEN p.RES_POL IS NOT NULL AND p.RES_POL < GETDATE() THEN 'Résiliée'
          WHEN p.SUS_POL IS NOT NULL AND p.SUS_POL < GETDATE() THEN 'Suspendue'
          WHEN p.EFF_POL IS NOT NULL AND p.EFF_POL > GETDATE() THEN 'En attente'
          WHEN p.STD_POL = 1 THEN 'Active'
          ELSE 'Inactive'
        END as status_display,
        -- Nombre de bénéficiaires
        (SELECT COUNT(*) FROM [core].[BENEF_POLICE] bp WHERE bp.COD_POL = p.COD_POL) as nb_beneficiaires
      FROM [core].[POLICE] p
      LEFT JOIN [core].[COMPAGNIE] c ON p.COD_ASS = c.COD_ASS
      LEFT JOIN [core].[SOUSCRIPTEUR] s ON p.COD_SOU = s.COD_SOU
      WHERE p.COD_POL = @id
    `;
    
    const policeResult = await pool.request()
      .input('id', sql.Int, parseInt(id))
      .query(policeQuery);
    
    if (policeResult.recordset.length === 0) {
      return res.status(404).json({
        success: false,
        message: `Police ${id} non trouvée`
      });
    }
    
    const police = policeResult.recordset[0];
    
    // 2. RÉCUPÉRER LES BÉNÉFICIAIRES DE LA POLICE
    const beneficiairesQuery = `
      SELECT 
        bp.NUM_BPO,
        bp.COD_BEN,
        bp.COD_POL,
        bp.COD_BPO,
        bp.ENT_BPO,
        bp.STE_BPO,
        bp.SOR_BPO,
        bp.STS_BPO,
        bp.MAT_BPO,
        bp.MAC_BPO,
        bp.PLF_BPO,
        bp.SUS_BPO,
        bp.REM_BPO,
        bp.DAT_DEME,
        bp.DAT_DEMS,
        bp.COD_PAY,
        b.NOM_BEN,
        b.PRE_BEN,
        b.FIL_BEN,
        b.SEX_BEN,
        b.NAI_BEN,
        b.TELEPHONE_MOBILE,
        b.EMAIL,
        b.PROFESSION,
        b.IDENTIFIANT_NATIONAL,
        py.LIB_PAY as PAYS_BENEFICIAIRE
      FROM [core].[BENEF_POLICE] bp
      LEFT JOIN [core].[BENEFICIAIRE] b ON bp.COD_BEN = b.ID_BEN
      LEFT JOIN [ref].[PAYS] py ON bp.COD_PAY = py.COD_PAY
      WHERE bp.COD_POL = @id
      ORDER BY bp.COD_BPO
    `;
    
    const beneficiairesResult = await pool.request()
      .input('id', sql.Int, parseInt(id))
      .query(beneficiairesQuery);
    
    const beneficiaires = beneficiairesResult.recordset;
    
    // Structure de réponse simplifiée
    const response = {
      police: police,
      beneficiaires: beneficiaires,
      metadata: {
        totalBeneficiaires: beneficiaires.length,
        dateGeneration: new Date().toISOString()
      }
    };
    
    return res.json({
      success: true,
      message: 'Police récupérée avec succès',
      police: response,
      timestamp: new Date().toISOString()
    });
    
  } catch (error) {
    console.error(`❌ Erreur récupération police ${req.params.id}:`, error);
    return res.status(500).json({
      success: false,
      message: 'Erreur lors de la récupération de la police',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined,
      timestamp: new Date().toISOString()
    });
  }
});


// Route pour créer une nouvelle police
app.post('/api/polices', authenticateToken, async (req, res) => {
  try {
    const policeData = req.body;
    const user = req.user;
    
    console.log('📝 Création d\'une nouvelle police:', policeData);
    
    // Validation des données requises
    if (!policeData.COD_ASS || isNaN(parseInt(policeData.COD_ASS))) {
      return res.status(400).json({
        success: false,
        message: 'La compagnie est obligatoire'
      });
    }
    
    if (!policeData.NUM_POL || policeData.NUM_POL.trim() === '') {
      return res.status(400).json({
        success: false,
        message: 'Le numéro de police est obligatoire'
      });
    }
    
    if (!policeData.EFF_POL) {
      return res.status(400).json({
        success: false,
        message: 'La date d\'effet est obligatoire'
      });
    }
    
    const pool = await dbConfig.getConnection();
    
    // Vérifier si le numéro de police existe déjà
    const checkQuery = `
      SELECT COUNT(*) as count
      FROM [core].[POLICE]
      WHERE NUM_POL = @numPol
    `;
    
    const checkResult = await pool.request()
      .input('numPol', sql.VarChar, policeData.NUM_POL.trim())
      .query(checkQuery);
    
    if (checkResult.recordset[0].count > 0) {
      return res.status(400).json({
        success: false,
        message: 'Une police avec ce numéro existe déjà'
      });
    }
    
    // Insertion de la police
    const insertQuery = `
      INSERT INTO [core].[POLICE] (
        COD_ASS, COD_SOU, COD_INT, NUM_POL, BIO_POL, EFF_POL, RES_POL, REM_POL, ORD_POL, EMP_POL,
        NUMR_POL, PEC_POL, COD_CNV, STD_POL, COD_RES, COD_TAR, COD_BAR, COD_PAI, COG_POL, COP_POL,
        PRM_POL, COD_CREUTIL, COD_MODUTIL, DAT_CREUTIL, DAT_MODUTIL, NAT_POL, TYP_POL, TYC_POL,
        COC_POL, IND_POL, DEM_POL, SUS_POL, VIG_POL, RSP_POL, TXA_POL, TXH_POL, AUT_POL, EMA_POL,
        MAJAUT_POL, AGEAUT_POL, DEL_POL, TTM_POL, TPL_POL, COM_POL, OBS_POL, DAT_CSS, MOD_POL,
        COD_CAR, MOD_CAR, PMT_POL, COD_PYR, COD_PAY
      ) VALUES (
        @COD_ASS, @COD_SOU, @COD_INT, @NUM_POL, @BIO_POL, @EFF_POL, @RES_POL, @REM_POL, @ORD_POL, @EMP_POL,
        @NUMR_POL, @PEC_POL, @COD_CNV, @STD_POL, @COD_RES, @COD_TAR, @COD_BAR, @COD_PAI, @COG_POL, @COP_POL,
        @PRM_POL, @COD_CREUTIL, @COD_MODUTIL, @DAT_CREUTIL, @DAT_MODUTIL, @NAT_POL, @TYP_POL, @TYC_POL,
        @COC_POL, @IND_POL, @DEM_POL, @SUS_POL, @VIG_POL, @RSP_POL, @TXA_POL, @TXH_POL, @AUT_POL, @EMA_POL,
        @MAJAUT_POL, @AGEAUT_POL, @DEL_POL, @TTM_POL, @TPL_POL, @COM_POL, @OBS_POL, @DAT_CSS, @MOD_POL,
        @COD_CAR, @MOD_CAR, @PMT_POL, @COD_PYR, @COD_PAY
      );
      SELECT SCOPE_IDENTITY() as newId;
    `;
    
    const request = pool.request();
    
    // Paramètres obligatoires
    request.input('COD_ASS', sql.Int, parseInt(policeData.COD_ASS));
    request.input('NUM_POL', sql.VarChar, policeData.NUM_POL.trim());
    request.input('EFF_POL', sql.Date, new Date(policeData.EFF_POL));
    request.input('COD_CREUTIL', sql.VarChar, user.username || 'SYSTEM');
    request.input('COD_MODUTIL', sql.VarChar, user.username || 'SYSTEM');
    request.input('DAT_CREUTIL', sql.DateTime, new Date());
    request.input('DAT_MODUTIL', sql.DateTime, new Date());
    
    // Paramètres optionnels (seulement quelques exemples, ajustez selon vos besoins)
    policeData.COD_SOU ? request.input('COD_SOU', sql.Int, parseInt(policeData.COD_SOU)) : request.input('COD_SOU', sql.Int, null);
    policeData.COD_INT ? request.input('COD_INT', sql.Int, parseInt(policeData.COD_INT)) : request.input('COD_INT', sql.Int, null);
    policeData.BIO_POL !== undefined ? request.input('BIO_POL', sql.Bit, policeData.BIO_POL ? 1 : 0) : request.input('BIO_POL', sql.Bit, null);
    policeData.RES_POL ? request.input('RES_POL', sql.Date, new Date(policeData.RES_POL)) : request.input('RES_POL', sql.Date, null);
    policeData.REM_POL ? request.input('REM_POL', sql.Char, policeData.REM_POL.substring(0, 1)) : request.input('REM_POL', sql.Char, null);
    policeData.ORD_POL ? request.input('ORD_POL', sql.VarChar, policeData.ORD_POL.trim()) : request.input('ORD_POL', sql.VarChar, null);
    
    // Continuez avec les autres champs...
    
    const insertResult = await request.query(insertQuery);
    const newId = insertResult.recordset[0].newId;
    
    // Récupérer la police créée
    const selectQuery = `
      SELECT p.*, c.LIB_ASS as NOM_COMPAGNIE
      FROM [core].[POLICE] p
      LEFT JOIN [core].[COMPAGNIE] c ON p.COD_ASS = c.COD_ASS
      WHERE p.COD_POL = @newId
    `;
    
    const selectResult = await pool.request()
      .input('newId', sql.Int, newId)
      .query(selectQuery);
    
    return res.status(201).json({
      success: true,
      message: 'Police créée avec succès',
      policeId: newId,
      police: selectResult.recordset[0],
      timestamp: new Date().toISOString()
    });
    
  } catch (error) {
    console.error('❌ Erreur création police:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur lors de la création de la police',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined,
      timestamp: new Date().toISOString()
    });
  }
});

