// Créer un nouveau backup
app.post('/api/config/backups/create', authenticateToken, async (req, res) => {
  try {
    const pool = await dbConfig.getConnection();
    const userId = req.user.id || req.user.ID_UTI;
    
    // Insérer un enregistrement de backup
    const query = `
      INSERT INTO [hcs_backoffice].[config].[BACKUP] 
      (NOM_FICHIER, DATE_CREATION, TAILLE_MO, TYPE_BACKUP, STATUT, 
       CHEMIN, DESCRIPTION, COD_UTILISATEUR, COD_CREUTIL, DAT_CREUTIL)
      VALUES (
        @nom_fichier,
        GETDATE(),
        @taille_mo,
        @type_backup,
        @statut,
        @chemin,
        @description,
        @cod_utilisateur,
        @cod_creutil,
        GETDATE()
      )
    `;
    
    const request = pool.request();
    request.input('nom_fichier', sql.NVarChar, `backup_${Date.now()}.bak`);
    request.input('taille_mo', sql.Decimal(10, 2), 0);
    request.input('type_backup', sql.NVarChar, 'FULL');
    request.input('statut', sql.NVarChar, 'EN_COURS');
    request.input('chemin', sql.NVarChar, '/backups/');
    request.input('description', sql.NVarChar, 'Backup automatique');
    request.input('cod_utilisateur', sql.Int, userId);
    request.input('cod_creutil', sql.Int, userId);
    
    await request.query(query);
    
    // Simuler une tâche de backup en arrière-plan
    setTimeout(async () => {
      try {
        const updatePool = await dbConfig.getConnection();
        const updateQuery = `
          UPDATE [hcs_backoffice].[config].[BACKUP] 
          SET STATUT = 'SUCCES', TAILLE_MO = @taille_mo
          WHERE NOM_FICHIER = @nom_fichier
        `;
        
        const updateRequest = updatePool.request();
        updateRequest.input('nom_fichier', sql.NVarChar, `backup_${Date.now()}.bak`);
        updateRequest.input('taille_mo', sql.Decimal(10, 2), Math.random() * 100 + 10); // Taille aléatoire entre 10 et 110 MB
        
        await updateRequest.query(updateQuery);
        await updatePool.close();
      } catch (updateError) {
        console.error('Erreur lors de la mise à jour du backup:', updateError);
      }
    }, 5000); // Simuler un délai de 5 secondes
    
    return res.status(200).json({
      success: true,
      message: 'Backup démarré avec succès. Le processus s\'exécute en arrière-plan.'
    });
    
  } catch (error) {
    console.error('❌ Erreur création backup:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur lors de la création du backup',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Restaurer un backup
app.post('/api/config/backups/:id/restore', authenticateToken, async (req, res) => {
  try {
    const { id } = req.params;
    const pool = await dbConfig.getConnection();
    
    // Vérifier si le backup existe
    const checkQuery = `
      SELECT * FROM [hcs_backoffice].[config].[BACKUP] 
      WHERE COD_BACKUP = @id AND STATUT = 'SUCCES'
    `;
    
    const checkResult = await pool.request()
      .input('id', sql.Int, id)
      .query(checkQuery);
    
    if (checkResult.recordset.length === 0) {
      return res.status(404).json({
        success: false,
        message: 'Backup non trouvé ou échoué'
      });
    }
    
    // Mettre à jour le statut pour indiquer la restauration en cours
    const updateQuery = `
      UPDATE [hcs_backoffice].[config].[BACKUP] 
      SET STATUT = 'RESTAURATION_EN_COURS'
      WHERE COD_BACKUP = @id
    `;
    
    await pool.request()
      .input('id', sql.Int, id)
      .query(updateQuery);
    
    // Simuler une restauration en arrière-plan
    setTimeout(async () => {
      try {
        const restorePool = await dbConfig.getConnection();
        const restoreUpdateQuery = `
          UPDATE [hcs_backoffice].[config].[BACKUP] 
          SET STATUT = 'RESTAURE'
          WHERE COD_BACKUP = @id
        `;
        
        await restorePool.request()
          .input('id', sql.Int, id)
          .query(restoreUpdateQuery);
        
        await restorePool.close();
      } catch (restoreError) {
        console.error('Erreur lors de la mise à jour du statut de restauration:', restoreError);
      }
    }, 10000); // Simuler un délai de 10 secondes
    
    return res.status(200).json({
      success: true,
      message: 'Restauration démarrée avec succès. Le processus s\'exécute en arrière-plan.'
    });
    
  } catch (error) {
    console.error('❌ Erreur restauration backup:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur lors de la restauration du backup',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Télécharger un backup
app.get('/api/config/backups/:id/download', authenticateToken, async (req, res) => {
  try {
    const { id } = req.params;
    const pool = await dbConfig.getConnection();
    
    const query = `
      SELECT * FROM [hcs_backoffice].[config].[BACKUP] 
      WHERE COD_BACKUP = @id AND STATUT = 'SUCCES'
    `;
    
    const result = await pool.request()
      .input('id', sql.Int, id)
      .query(query);
    
    if (result.recordset.length === 0) {
      return res.status(404).json({
        success: false,
        message: 'Backup non trouvé ou échoué'
      });
    }
    
    const backup = result.recordset[0];
    
    // Simuler le téléchargement d'un fichier
    res.setHeader('Content-Type', 'application/octet-stream');
    res.setHeader('Content-Disposition', `attachment; filename="${backup.NOM_FICHIER}"`);
    
    // Créer un fichier factice pour le téléchargement
    const dummyContent = `Backup: ${backup.NOM_FICHIER}\nDate: ${backup.DATE_CREATION}\nTaille: ${backup.TAILLE_MO} MB\n`;
    res.send(dummyContent);
    
  } catch (error) {
    console.error('❌ Erreur téléchargement backup:', error);
    return res.status(500).json({
      success: false,
      message: 'Erreur lors du téléchargement du backup',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

