          ['NAT456123789', '', 'DURAND', 'Pierre', 'M', '1975-11-30', 'Marseille, France', 'FR', '+33712345678', '', 'pierre.durand@email.com', 'O', '-', 'ENFANT', '1', 'Étudiant', 'Université', 'Célibataire', '789 Boulevard Sud', 'REG003', 'T003', 'Rurale', 'Maison', 1, 0, 15, 'Vélo']
